import React from "react";
import Sidebar from "../components/Sidebar";
import Navbar from "../components/Navbar";

function Dashboard() {
    return (
        <div style={{ display: "flex" }}>

            <Sidebar />

            <div style={{ flex: 1 }}>
                <Navbar />

                <div style={{ padding: "20px" }}>
                    <h1>Welcome to HRMS Dashboard</h1>
                </div>

            </div>

        </div>
    );
}

export default Dashboard;
